<?php
use App\Models\CustomerPurchaseRequest; use App\Support\AuthorizationScope;
use function Livewire\Volt\computed; use function Livewire\Volt\layout; use function Livewire\Volt\state;
layout('layouts.app'); state(['status'=>'','search'=>'']);
$requests=computed(function(){ $user=auth()->user();$query=CustomerPurchaseRequest::withoutGlobalScope(\App\Models\Scopes\CompanyScope::class)->with(['customer','branch'])->where('company_id',$user->company_id);if(AuthorizationScope::scopeFor($user,'report_scope',AuthorizationScope::BRANCH)!==AuthorizationScope::COMPANY)$query->where('branch_id',$user->branch_id);return $query->when($this->status,fn($q)=>$q->where('status',$this->status))->when($this->search,fn($q)=>$q->where(fn($s)=>$s->where('request_number','like',"%{$this->search}%")->orWhereHas('customer',fn($c)=>$c->where('name','like',"%{$this->search}%"))))->latest()->paginate(20);});
?>
<div><x-page-header title="{{ __('application.customer_requests_bc510608') }}" description="{{ __('application.review_b2b_portal_requests_and_prepare_quotations_d52996e5') }}" :breadcrumbs="['Dashboard'=>route('dashboard'),'Customer Requests'=>null]"/><x-card><div class="mb-4 grid gap-3 sm:grid-cols-2"><input wire:model.live.debounce.300ms="search" placeholder="{{ __('application.request_or_customer_4f803398') }}" class="rounded-xl border-slate-200 dark:bg-navy-950"><select wire:model.live="status" class="rounded-xl border-slate-200 dark:bg-navy-950"><option value="">{{ __('application.all_statuses_6405179d') }}</option>@foreach(\App\Models\CustomerPurchaseRequest::STATUSES as $value)<option value="{{ $value }}">{{ \App\Support\UiText::label($value) }}</option>@endforeach</select></div><x-table :headers="[__('application.request_4aed03ca'),__('application.customer_0e85749a'),__('application.branch_1627510b'),__('application.items_44d25b5d'),__('application.submitted_2e00359b'),__('application.status_bae7d5be'),'']">@forelse($this->requests as $request)<tr><td class="px-4 py-3 font-black">{{ $request->request_number }}</td><td class="px-4 py-3">{{ $request->customer->displayName() }}</td><td class="px-4 py-3">{{ $request->branch?->name }}</td><td class="px-4 py-3">{{ $request->items()->count() }}</td><td class="px-4 py-3">{{ $request->submitted_at->locale(app()->getLocale())->translatedFormat('d M Y H:i') }}</td><td class="px-4 py-3">{{ \App\Support\UiText::label($request->status) }}</td><td class="px-4 py-3"><a href="{{ route('customer-requests.show',$request) }}" wire:navigate class="font-bold text-build-orange">{{ __('application.review_e29a79fe') }}</a></td></tr>@empty<tr><td colspan="7" class="px-4 py-10 text-center text-slate-500">{{ __('application.no_customer_requests_found_11e63977') }}</td></tr>@endforelse</x-table><div class="mt-4">{{ $this->requests->links() }}</div></x-card></div>
